int comedi_ioctl_devinfo(struct comedi_device *dev, struct comedi_devinfo __user *arg, struct file *file)
{
	struct comedi_devinfo info;
	int read_subdev = -1;
	int write_subdev = -1;
	int i;

	info.version_code = dev->version_code;
	info.n_subdevices = dev->n_subdevices;

	for (i = 0; i < dev->n_subdevices; i++) {
		if (dev->subdevices[i].type == COMEDI_SUBD_AI && dev->subdevices[i].read_subdev >= 0)
			read_subdev = i;
		if (dev->subdevices[i].type == COMEDI_SUBD_AO && dev->subdevices[i].write_subdev >= 0)
			write_subdev = i;
	}

	strcpy(info.driver_name, dev->driver->driver_name);
	strcpy(info.board_name, dev->board_name);
	info.read_subdev = read_subdev;
	info.write_subdev = write_subdev;

	if (copy_to_user(arg, &info, sizeof(info)))
		return -EFAULT;

	return 0;
}

int comedi_ioctl_devinfo(struct comedi_device *dev, struct comedi_devinfo __user *arg, struct file *file)
{
	struct comedi_devinfo info;
	int read_subdev = -1;
	int write_subdev = -1;
	int i;

	memset(&info, 0, sizeof(info));
	info.version_code = COMEDI_VERSION_CODE;
	info.n_subdevices = dev->n_subdevices;
	strlcpy(info.driver_name, dev->driver->driver_name, sizeof(info.driver_name));
	strlcpy(info.board_name, dev->board_name, sizeof(info.board_name));

	for (i = 0; i < dev->n_subdevices; i++) {
		if (dev->subdevices[i].type == COMEDI_SUBD_UNUSED)
			continue;
		if (dev->subdevices[i].subdev_flags & SDF_READ)
			read_subdev = i;
		if (dev->subdevices[i].subdev_flags & SDF_WRITE)
			write_subdev = i;
	}
	info.read_subdev = read_subdev;
	info.write_subdev = write_subdev;

	if (copy_to_user(arg, &info, sizeof(info)))
		return -EFAULT;

	return 0;
}

